template:
% 参数由系统自动注入：\def\radius{2} \def\height{4} \def\showcone{1} \def\shownet{0} \def\showslant{1} \def\showaxis{0} \def\showbaseradius{0} \def\showcentralangle{0} \def\labelp{P} \def\labelo{O} \def\labela{A} \def\labelb{B}
% 母线 l = sqrt(r^2 + h^2)；侧面展开成扇形，弧长 = 底面周长 2*pi*r，故扇形圆心角 = 360*r/l（恒小于 360）
\pgfmathsetmacro{\slant}{sqrt(\radius*\radius + \height*\height)}
\pgfmathsetmacro{\netang}{360*\radius/\slant}
\pgfmathsetmacro{\halfang}{\netang/2}
% 底面椭圆的短半轴（透视压缩系数 0.3）
\pgfmathsetmacro{\erad}{0.3*\radius}
% 展开扇形以顶点 Q 为心、绕 0 度方向左右各张开 halfang；先算它相对 Q 的包围盒
\pgfmathsetmacro{\netxlo}{min(0, \slant*cos(\halfang))}
\pgfmathsetmacro{\netxhi}{\slant}
\pgfmathsetmacro{\netyhi}{\slant*sin(min(\halfang,90))}
\pgfmathsetmacro{\gapx}{0.5*\radius}
\pgfmathsetmacro{\Qx}{\radius + \gapx - \netxlo}
\pgfmathsetmacro{\Qy}{(\height - \erad)/2}
% 整图包围盒：立体图 x in [-r,r]、y in [-erad,h]；按开关合并展开图部分
\ifnum\showcone>0
  \pgfmathsetmacro{\bxlo}{-\radius}
  \pgfmathsetmacro{\bxhi}{\radius}
  \pgfmathsetmacro{\bylo}{-\erad}
  \pgfmathsetmacro{\byhi}{\height}
  \ifnum\shownet>0
    \pgfmathsetmacro{\bxhi}{\Qx + \netxhi}
    \pgfmathsetmacro{\bylo}{min(\bylo, \Qy - \netyhi)}
    \pgfmathsetmacro{\byhi}{max(\byhi, \Qy + \netyhi)}
  \fi
\else
  \pgfmathsetmacro{\bxlo}{\Qx + \netxlo}
  \pgfmathsetmacro{\bxhi}{\Qx + \netxhi}
  \pgfmathsetmacro{\bylo}{\Qy - \netyhi}
  \pgfmathsetmacro{\byhi}{\Qy + \netyhi}
\fi
% 视觉归一化：把整图较长的一边缩放到约 6.4cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\extent}{max(\bxhi - \bxlo, \byhi - \bylo)}
\pgfmathsetmacro{\figscale}{6.4/\extent}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ---------- 圆锥立体图 ----------
  \ifnum\showcone>0
    \coordinate (O) at (0,0);
    \coordinate (P) at (0,\height);
    \coordinate (A) at (\radius,0);
    \coordinate (B) at (-\radius,0);
    % 底面圆的透视椭圆：后半圈（上方）虚线，前半圈（下方）实线
    \draw[thick, dashed] (\radius,0) arc[x radius=\radius, y radius=\erad, start angle=0, end angle=180];
    \draw[thick] (-\radius,0) arc[x radius=\radius, y radius=\erad, start angle=180, end angle=360];
    % 两条母线 PA、PB
    \ifnum\showslant>0
      \draw[thick] (P) -- (A);
      \draw[thick] (P) -- (B);
    \fi
    % 底面半径 OA
    \ifnum\showbaseradius>0
      \draw[thick] (O) -- (A);
    \fi
    % 圆锥的高 PO + 直角记号（高垂直于底面）
    \ifnum\showaxis>0
      \draw[thick, dashed] (P) -- (O);
      \pgfmathsetmacro{\rms}{min(0.24/\figscale, \radius*0.22, \height*0.14)}
      \draw[thick] (\rms,0) -- (\rms,\rms) -- (0,\rms);
    \fi
    \fill (P) circle [radius=\dotr pt];
    \node[above=2pt] at (P) {$\labelp$};
    \fill (A) circle [radius=\dotr pt];
    \node[right=2pt] at (A) {$\labela$};
    \fill (B) circle [radius=\dotr pt];
    \node[left=2pt] at (B) {$\labelb$};
    \fill (O) circle [radius=\dotr pt];
    \node[below right=1pt] at (O) {$\labelo$};
  \fi
  % ---------- 侧面展开扇形 ----------
  \ifnum\shownet>0
    \coordinate (Q) at (\Qx,\Qy);
    \pgfmathsetmacro{\nax}{\Qx + \slant*cos(-\halfang)}
    \pgfmathsetmacro{\nay}{\Qy + \slant*sin(-\halfang)}
    \draw[thick] (Q) -- (\nax,\nay) arc[start angle=-\halfang, end angle=\halfang, radius=\slant] -- cycle;
    % 扇形圆心角的角弧
    \ifnum\showcentralangle>0
      \pgfmathsetmacro{\narcr}{min(0.5/\figscale, \slant*0.26)}
      \draw[thick] ({\Qx + \narcr*cos(-\halfang)},{\Qy + \narcr*sin(-\halfang)}) arc[start angle=-\halfang, end angle=\halfang, radius=\narcr];
    \fi
    \fill (Q) circle [radius=\dotr pt];
    \node[left=3pt] at (Q) {$\labelp$};
    \fill ({\Qx + \slant*cos(-\halfang)},{\Qy + \slant*sin(-\halfang)}) circle [radius=\dotr pt];
    \node at ({\Qx + 1.07*\slant*cos(-\halfang)},{\Qy + 1.07*\slant*sin(-\halfang)}) {$\labela$};
    \fill ({\Qx + \slant*cos(\halfang)},{\Qy + \slant*sin(\halfang)}) circle [radius=\dotr pt];
    \node at ({\Qx + 1.07*\slant*cos(\halfang)},{\Qy + 1.07*\slant*sin(\halfang)}) {$\labelb$};
  \fi
\end{tikzpicture}
